package org.xbill.DNS;

import static org.junit.Assert.*;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.net.InetAddress;
import java.util.Iterator;
import java.util.List;

import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.ExpectedException;

/**
 * JUnit‑4 test suite for {@link Zone}.
 *
 * The suite follows the “three‑expert” workflow described in the task:
 *   1. List public methods
 *   2. Provide a basic test for each method
 *   3. Identify edge cases / exceptional paths
 *   4. Add tests for those cases
 *   5. Merge everything into this file.
 */
public class ZoneTest {

    /* ---------------------------------------------------------------------- */
    /*  Helper data used by many tests                                        */
    /* ---------------------------------------------------------------------- */

    private Name origin;
    private SOARecord soa;
    private NSRecord ns1;
    private NSRecord ns2;
    private ARecord aRecord;          // simple A record for lookup tests
    private Zone zone;                 // zone created from the record array ctor

    @Rule
    public ExpectedException thrown = ExpectedException.none();

    /**
     * Build a minimal but fully‑valid zone containing:
     *   – exactly one SOA record (origin)
     *   – two NS records (origin)
     *   – one A record (foo.origin)
     */
    @Before
    public void setUp() throws Exception {
        origin = Name.fromString("example.com.");

        // SOA (origin)
        soa = new SOARecord(
                origin,
                DClass.IN,
                3600,
                Name.fromString("ns1.example.com."),
                Name.fromString("hostmaster.example.com."),
                2023101501L,   // serial
                7200,          // refresh
                3600,          // retry
                1209600,       // expire
                3600);         // minimum

        // two NS records at the zone apex
        ns1 = new NSRecord(origin, DClass.IN, 3600,
                Name.fromString("ns1.example.com."));
        ns2 = new NSRecord(origin, DClass.IN, 3600,
                Name.fromString("ns2.example.com."));

        // an A record for a child name
        aRecord = new ARecord(
                Name.fromString("www.example.com."),
                DClass.IN,
                3600,
                InetAddress.getByName("192.0.2.1"));

        // Build the zone via the var‑args constructor (the most direct way)
        zone = new Zone(origin, soa, ns1, ns2, aRecord);
    }

    /* ---------------------------------------------------------------------- */
    /*  1. Public method signatures (for reference)                           */
    /* ---------------------------------------------------------------------- */
    //  public int getDClass()
    //  public RRset getNS()
    //  public SOARecord getSOA()
    //  public Iterator<RRset> iterator()
    //  public Iterator<RRset> AXFR()
    //  public <T extends Record> void addRecord(T r)
    //  public void removeRecord(Record r)
    //  public void addRRset(RRset rrset)
    //  public void removeRRset(Name name, int type)
    //  public RRset findExactMatch(Name name, int type)
    //  public SetResponse findRecords(Name name, int type)
    //  public String toMasterFile()
    //  public String toString()
    //  public ZoneIterator iterator()          // implemented via Iterable<RRset>

    /* ---------------------------------------------------------------------- */
    /*  2. Basic functionality tests                                           */
    /* ---------------------------------------------------------------------- */

    @Test
    public void testGetDClass() {
        assertEquals(DClass.IN, zone.getDClass());
    }

    @Test
    public void testGetSOA() {
        assertSame(soa, zone.getSOA());
    }

    @Test
    public void testGetNS() {
        RRset nsSet = zone.getNS();
        assertNotNull(nsSet);
        assertEquals(Type.NS, nsSet.getType());
        // the set should contain exactly the two NS records we added
        List<Record> records = nsSet.rrs();
        assertEquals(2, records.size());
        assertTrue(records.contains(ns1));
        assertTrue(records.contains(ns2));
    }

    @Test
    public void testIteratorOrder() {
        Iterator<RRset> it = zone.iterator();
        // First set must be the SOA, second the NS set
        assertTrue(it.hasNext());
        RRset first = it.next();
        assertEquals(Type.SOA, first.getType());

        assertTrue(it.hasNext());
        RRset second = it.next();
        assertEquals(Type.NS, second.getType());

        // The remaining sets include the A record
        assertTrue(it.hasNext());
        RRset third = it.next();
        assertEquals(Type.A, third.getType());

        assertFalse(it.hasNext());
    }

    @Test
    public void testAXFRIncludesTrailingSOA() {
        Iterator<RRset> axfr = zone.AXFR();
        // Consume all normal entries
        while (axfr.hasNext()) {
            RRset set = axfr.next();
            // nothing to assert inside the loop – just iterate
        }
        // After the normal iteration the iterator should still have one more SOA
        // (the trailing one). The previous loop ends when hasNext() becomes false,
        // so we need a fresh iterator to verify the trailing SOA.
        Iterator<RRset> fresh = zone.AXFR();
        int count = 0;
        RRset last = null;
        while (fresh.hasNext()) {
            last = fresh.next();
            count++;
        }
        // The last set must be the SOA again
        assertNotNull(last);
        assertEquals(Type.SOA, last.getType());
        // Total count = (normal sets) + 1 trailing SOA
        // Normal sets: SOA, NS, A  => 3, plus trailing SOA => 4
        assertEquals(4, count);
    }

    @Test
    public void testAddRecordAddsNewRRset() throws IOException {
        // Add a TXT record that does not yet exist in the zone
        TXTRecord txt = new TXTRecord(
                Name.fromString("txt.example.com."),
                DClass.IN,
                3600,
                "hello");
        zone.addRecord(txt);

        RRset found = zone.findExactMatch(txt.getName(), Type.TXT);
        assertNotNull(found);
        assertEquals(1, found.size());
        assertEquals(txt, found.first());
    }

    @Test
    public void testAddRecordMergesIntoExistingRRset() throws IOException {
        // Add a second A record for the same name
        ARecord a2 = new ARecord(
                aRecord.getName(),
                DClass.IN,
                3600,
                InetAddress.getByName("192.0.2.2"));
        zone.addRecord(a2);

        RRset aSet = zone.findExactMatch(aRecord.getName(), Type.A);
        assertNotNull(aSet);
        assertEquals(2, aSet.size());
        assertTrue(aSet.rrs().contains(aRecord));
        assertTrue(aSet.rrs().contains(a2));
    }

    @Test
    public void testRemoveRecordRemovesOnlyOneRR() throws IOException {
        // Remove one of the NS records; the other must stay
        zone.removeRecord(ns1);
        RRset nsSet = zone.getNS();
        assertEquals(1, nsSet.size());
        assertTrue(nsSet.rrs().contains(ns2));
    }

    @Test
    public void testRemoveRecordLastNSThrows() throws IOException {
        // Remove both NS records – the second removal must fail
        zone.removeRecord(ns1);
        thrown.expect(IllegalArgumentException.class);
        thrown.expectMessage("Cannot remove all NS");
        zone.removeRecord(ns2);
    }

    @Test
    public void testAddRRsetReplacesExisting() throws IOException {
        // Build a new NS RRset (different target) and add it – should replace
        NSRecord nsNew = new NSRecord(
                origin,
                DClass.IN,
                3600,
                Name.fromString("ns3.example.com."));
        RRset newNsSet = new RRset(nsNew);
        zone.addRRset(newNsSet);

        RRset stored = zone.getNS();
        assertEquals(1, stored.size());
        assertEquals(nsNew, stored.first());
    }

    @Test
    public void testRemoveRRsetRemovesSpecificType() throws IOException {
        // Remove the A record RRset via removeRRset
        zone.removeRRset(aRecord.getName(), Type.A);
        RRset aSet = zone.findExactMatch(aRecord.getName(), Type.A);
        assertNull(aSet);
    }

    @Test
    public void testFindExactMatch() {
        RRset result = zone.findExactMatch(ns1.getName(), Type.NS);
        assertNotNull(result);
        assertEquals(ns1.getName(), result.getName());
        assertEquals(Type.NS, result.getType());
    }

    @Test
    public void testFindExactMatchMissingReturnsNull() {
        Name unknown = Name.fromString("nosuch.example.com.");
        assertNull(zone.findExactMatch(unknown, Type.A));
    }

    @Test
    public void testFindRecordsExactMatchSuccess() {
        SetResponse resp = zone.findRecords(aRecord.getName(), Type.A);
        assertTrue(resp.isSuccessful());
        List<RRset> answers = resp.answers();
        assertEquals(1, answers.size());
        RRset aSet = answers.get(0);
        assertEquals(Type.A, aSet.getType());
        assertEquals(aRecord.getName(), aSet.getName());
    }

    @Test
    public void testFindRecordsCNAMEFallback() throws IOException {
        // Create a CNAME for foo.example.com -> www.example.com
        CNAMERecord cname = new CNAMERecord(
                Name.fromString("foo.example.com."),
                DClass.IN,
                3600,
                Name.fromString("www.example.com."));
        zone.addRecord(cname);

        SetResponse resp = zone.findRecords(cname.getName(), Type.A);
        assertTrue(resp.isCNAME());
        assertEquals(cname, resp.getCNAME());
    }

    @Test
    public void testFindRecordsNXDOMAIN() {
        Name outside = Name.fromString("outside.com.");
        SetResponse resp = zone.findRecords(outside, Type.A);
        assertTrue(resp.isNXDOMAIN());
    }

    @Test
    public void testToMasterFileContainsAllRecords() {
        String master = zone.toMasterFile();
        // Very light validation – ensure that the SOA, NS and A appear as text
        assertTrue(master.contains("example.com."));
        assertTrue(master.contains("ns1.example.com."));
        assertTrue(master.contains("www.example.com."));
    }

    @Test
    public void testToStringDelegatesToMasterFile() {
        assertEquals(zone.toMasterFile(), zone.toString());
    }

    /* ---------------------------------------------------------------------- */
    /*  3. Edge‑case & exception tests                                        */
    /* ---------------------------------------------------------------------- */

    @Test
    public void testConstructorNullNameThrows() throws IOException {
        thrown.expect(IllegalArgumentException.class);
        thrown.expectMessage("no zone name specified");
        new Zone(null, new ByteArrayInputStream(new byte[0]));
    }

    @Test
    public void testConstructorNullInputStreamThrows() throws IOException {
        thrown.expect(IllegalArgumentException.class);
        thrown.expectMessage("no input stream specified");
        new Zone(origin, (InputStream) null);
    }

    @Test
    public void testConstructorMissingSOAThrows() throws IOException {
        // Build a zone without SOA – validation should fail
        Record[] records = new Record[]{ns1, ns2};
        thrown.expect(IOException.class);
        thrown.expectMessage("exactly 1 SOA must be specified");
        new Zone(origin, records);
    }

    @Test
    public void testConstructorMissingNSThrows() throws IOException {
        // Build a zone with SOA but no NS
        Record[] records = new Record[]{soa};
        thrown.expect(IOException.class);
        thrown.expectMessage("no NS set specified");
        new Zone(origin, records);
    }

    @Test
    public void testAddRecordNullThrows() {
        thrown.expect(IllegalArgumentException.class);
        thrown.expectMessage("r must not be null");
        zone.addRecord(null);
    }

    @Test
    public void testAddRecordSOAWithWrongOwnerThrows() throws IOException {
        // SOA whose owner is not the zone origin
        SOARecord badSoa = new SOARecord(
                Name.fromString("bad.example.com."),
                DClass.IN,
                3600,
                Name.fromString("ns1.example.com."),
                Name.fromString("hostmaster.example.com."),
                2023101502L,
                7200, 3600, 1209600, 3600);
        thrown.expect(IllegalArgumentException.class);
        thrown.expectMessage("SOA owner");
        zone.addRecord(badSoa);
    }

    @Test
    public void testAddRecordOutsideZoneThrows() throws IOException {
        Record outRec = new ARecord(
                Name.fromString("outside.com."),
                DClass.IN,
                3600,
                InetAddress.getByName("203.0.113.1"));
        thrown.expect(IllegalArgumentException.class);
        thrown.expectMessage("subdomain");
        zone.addRecord(outRec);
    }

    @Test
    public void testRemoveRecordNullThrows() {
        thrown.expect(IllegalArgumentException.class);
        thrown.expectMessage("r must not be null");
        zone.removeRecord(null);
    }

    @Test
    public void testRemoveRecordSOAThrows() {
        thrown.expect(IllegalArgumentException.class);
        thrown.expectMessage("Cannot remove SOA");
        zone.removeRecord(soa);
    }

    @Test
    public void testAddRRsetNullThrows() {
        thrown.expect(IllegalArgumentException.class);
        thrown.expectMessage("rrset must not be null");
        zone.addRRset(null);
    }

    @Test
    public void testAddRRsetInvalidSOATypeThrows() throws IOException {
        // Build an RRset that contains two SOA records – violates the rule of exactly one
        RRset badSet = new RRset(soa, new SOARecord(
                origin,
                DClass.IN,
                3600,
                Name.fromString("ns1.example.com."),
                Name.fromString("hostmaster.example.com."),
                2023101503L,
                7200, 3600, 1209600, 3600));
        thrown.expect(IllegalArgumentException.class);
        thrown.expectMessage("exactly 1 SOA must be specified");
        zone.addRRset(badSet);
    }

    @Test
    public void testRemoveRRsetNullNameThrows() throws IOException {
        thrown.expect(IllegalArgumentException.class);
        thrown.expectMessage("name must not be null");
        zone.removeRRset(null, Type.A);
    }

    @Test
    public void testRemoveRRsetInvalidTypeThrows() throws IOException {
        thrown.expect(InvalidTypeException.class);
        zone.removeRRset(origin, 0); // 0 is not a valid DNS type
    }

    @Test
    public void testFindExactMatchNullNameThrows() {
        thrown.expect(IllegalArgumentException.class);
        thrown.expectMessage("name must not be null");
        zone.findExactMatch(null, Type.A);
    }

    @Test
    public void testFindExactMatchInvalidTypeThrows() {
        thrown.expect(InvalidTypeException.class);
        zone.findExactMatch(origin, 0);
    }

    @Test
    public void testFindRecordsNullNameThrows() {
        thrown.expect(IllegalArgumentException.class);
        thrown.expectMessage("name must not be null");
        zone.findRecords(null, Type.A);
    }

    @Test
    public void testFindRecordsInvalidTypeThrows() {
        thrown.expect(InvalidTypeException.class);
        zone.findRecords(origin, 0);
    }

    @Test
    public void testIteratorRemoveWithoutNextThrows() {
        Iterator<RRset> it = zone.iterator();
        thrown.expect(IllegalStateException.class);
        it.remove(); // remove called before next()
    }

    @Test
    public void testZoneIteratorRemoveSOAThrows() {
        Iterator<RRset> it = zone.iterator();
        // first element is SOA
        RRset first = it.next();
        assertEquals(Type.SOA, first.getType());

        thrown.expect(IllegalArgumentException.class);
        it.remove(); // attempt to remove the SOA via the iterator
    }

    @Test
    public void testZoneIteratorRemoveNSAllowed() {
        Iterator<RRset> it = zone.iterator();
        // skip SOA
        it.next();
        // second element is NS
        RRset nsSet = it.next();
        assertEquals(Type.NS, nsSet.getType());

        // Removing NS via iterator is allowed only if more than one NS remains.
        // Our zone has two NS records, so removal should succeed.
        it.remove();

        // After removal, the NS set should be gone from the zone
        assertNull(zone.getNS());
    }

    /* ---------------------------------------------------------------------- */
    /*  4. Merge – complete test file (already merged above)                 */
    /* ---------------------------------------------------------------------- */
}
